<div class="hero"><div><p class="eyebrow">UN CLUB. OTTO MONDI.</p><div class="profile-heading"><span id="profile-avatar" class="hero-avatar" hidden></span><div><h1 id="title"><?=($campusPage??null)==="world_center"?"World Center":(($campusPage??null)==="the_dugout"?"The Dugout":"Club House")?></h1><p id="subtitle">Tutti i manager IMC. Tutta la carriera nei club.</p></div></div><div class="hero-tags"><span>Carriera globale</span><span>Club e Nations</span><span>IMC-001–IMC-008</span></div></div><div class="hero-mark" aria-hidden="true">CH<span>CLUB HOUSE</span></div></div></header><main>
<nav class="hub-sections" aria-label="Sezioni Club House"><?php require __DIR__.'/campus-links.php'; ?></nav>
